document.addEventListener('DOMContentLoaded', function() {
    const searchInput = document.getElementById('search-input');
    const searchButton = document.getElementById('search-button');

    searchButton.addEventListener('click', function(event) {
        event.preventDefault(); // Impede o comportamento padrão do botão

        const searchTerm = searchInput.value;

        if (searchTerm.trim() === '') {
            alert('Por favor, insira um termo de pesquisa.');
            return;
        }

        // Aqui você implementaria a lógica de busca real
        // Por exemplo, buscar dados de um servidor ou filtro de conteúdo
        console.log('Pesquisando por:', searchTerm);

        // Exemplo: Adicionando um marcador de posição para os resultados
        const contentDiv = document.querySelector('.content');
        contentDiv.innerHTML = `<p>Você pesquisou por: <strong>${searchTerm}</strong>.  Adicione mais funcionalidade aqui.</p>`;

        // Limpar a entrada
        searchInput.value = '';
    });

    // Opcional: Adicionar funcionalidade de pesquisa com tecla Enter
    searchInput.addEventListener('keydown', function(event) {
        if (event.key === 'Enter') {
            searchButton.click();
        }
    });
});
