        $for_new_users = $this->input->post('for_new_users');
        $is_reusable = $this->input->post('is_reusable');
        $data = [
            'code' => $code,
            'discount_type' => $discount_type,
            'discount_value' => $discount_value,
            'valid_from' => date('Y-m-d H:i:s', mktime($valid_from['hour'], $valid_from['minute'], $valid_from['second'], $valid_from['month'], $valid_from['day'], $valid_from['year'])),
            'valid_to' => date('Y-m-d H:i:s', mktime($valid_to['hour'], $valid_to['minute'], $valid_to['second'], $valid_to['month'], $valid_to['day'], $valid_to['year'])),
            'for_new_users' => ($for_new_users == 1) ? 1 : 0,
            'is_reusable' => ($is_reusable == 1) ? 1 : 0,
        ];

        $existing_coupon = $this->coupons_model->get_coupon_by_code($code);
        if ($existing_coupon && $existing_coupon->id != $id) {
            // O código do cupom já está em uso por outro cupom
            set_alert('danger', 'O código do cupom já está em uso. Por favor, escolha um código diferente.');
            redirect($_SERVER['HTTP_REFERER']);
        }

        if ($id) {
            // Atualizar cupom existente
            $this->coupons_model->update_coupon($id, $data);
        } else {
            // Inserir novo cupom
            $this->coupons_model->insert_coupon($data);
        }

        // Redirecionar para a página de cupons
        set_alert('success', 'Cupom salvo com sucesso!');
        redirect(admin_url('ecommerce/coupons'));
    }
}



